mapper.sql:
FROM access_clean_package_item i
WHERE i.disposition = 'INCLUDED'
AND i.swing_time >= #{startTime}
AND i.swing_time <= #{endTime}

    AND i.channel_code IN
    #{ch}


    AND  = 'ENTER'


    AND  = 'EXIT'

mapper.select:
SELECT
    (SELECT COUNT(DISTINCT )
     FROM access_clean_package_item i
     WHERE i.disposition = 'INCLUDED'
     AND i.swing_time >= #{startTime}
     AND i.swing_time <= #{endTime}

         AND i.channel_code IN
         #{ch}


         AND  = 'ENTER'


         AND  = 'EXIT'

    ) AS uniqueUsers,
    (SELECT COUNT(DISTINCT g.gname) FROM (
        SELECT TRIM(ap.project_group_name) AS gname
        FROM access_clean_package_item i
        INNER JOIN aro_personnel ap ON ap.user_id = i.mapping_user_id
            AND ap.project_group_name IS NOT NULL AND TRIM(ap.project_group_name) != ''
        WHERE i.disposition = 'INCLUDED'
        AND i.swing_time >= #{startTime}
        AND i.swing_time <= #{endTime}

            AND i.channel_code IN
            #{ch}


            AND  = 'ENTER'


            AND  = 'EXIT'

        UNION
        SELECT '未标注课题组' AS gname
        FROM access_clean_package_item i
        WHERE i.disposition = 'INCLUDED'
        AND i.swing_time >= #{startTime}
        AND i.swing_time <= #{endTime}

            AND i.channel_code IN
            #{ch}


            AND  = 'ENTER'


            AND  = 'EXIT'

        AND (
            TRIM(COALESCE(i.mapping_user_id, '')) = ''
            OR NOT EXISTS (
                SELECT 1 FROM aro_personnel ap2
                WHERE ap2.user_id = i.mapping_user_id
                  AND ap2.project_group_name IS NOT NULL AND TRIM(ap2.project_group_name) != ''
            )
        )
    ) g) AS uniqueGroups

SELECT i.mapping_user_id AS userId, i.person_name AS name, CASE WHEN COALESCE(NULLIF(i.direction_override, ''), i.direction) = 'ENTER' THEN 1 WHEN COALESCE(NULLIF(i.direction_override, ''), i.direction) = 'EXIT' THEN 2 ELSE NULL END AS accessType, DATE_FORMAT(i.swing_time, '%Y-%m-%d %H:%i:%s') AS createTime, COALESCE(mr.region_name, '清洗通道') AS areaName, COALESCE(mr.room_name, i.channel_name, i.channel_code) AS roomName, COALESCE(mr.room_id, CONCAT('ch:', i.channel_code)) AS roomId, i.department_id AS departmentId, (SELECT GROUP_CONCAT(DISTINCT ap.project_group_name SEPARATOR ',') FROM aro_personnel ap WHERE ap.user_id = i.mapping_user_id AND ap.project_group_name IS NOT NULL AND ap.project_group_name != '' LIMIT 3) AS projectGroupNames, i.audience_type AS audienceType FROM access_clean_package_item i LEFT JOIN room_mapping_channel mc ON mc.channel_code = i.channel_code LEFT JOIN room_mapping_room mr ON mr.room_id = mc.room_id WHERE i.disposition = 'INCLUDED' AND i.swing_time >= #{startTime} AND i.swing_time <= #{endTime}
AND i.channel_code IN #{ch}
AND = 'ENTER'
AND = 'EXIT'
ORDER BY i.swing_time ASC LIMIT 500000

where.if:
AND (
    EXISTS (
        SELECT 1 FROM twin_dahua_swing_record s
        WHERE s.id = i.swing_row_id
          AND s.task_id = #{statsPullTaskId}
          AND s.pull_task_type = 'STATS'
    )
    OR (
        i.swing_row_id IS NULL
        AND EXISTS (
            SELECT 1 FROM access_clean_execution_log e
            WHERE e.id = i.last_run_id AND e.stats_pull_task_id = #{statsPullTaskId}
        )
    )
)

